		return ErrMismatch
	}
	s, e := object(in.Settings)

if e != nil {
	return e
}
if s["decryption"] != "none" || s["encryption"] != "none" {
	return fmt.Errorf("%w: vless crypto", ErrMismatch)
}
clients, ok := s["clients"].([]any)
if !ok || len(clients) == 0 {

	return fmt.Errorf("%w: clients", ErrMismatch)
